/* Referral Outreach Queue Page — Operations Console
 *
 * Allows the operator to review personalized cold referral request message drafts
 * generated by the Referral Outreach Agent for company contacts, alumni, and recruiters.
 *
 * Enforces:
 *   - Manual outreach copy & send (prevents automated LinkedIn/email spam bans)
 *   - One-click Copy to Clipboard for draft subject and body
 *   - One-click LinkedIn Alumni Search link generation
 *   - Mark as Sent database event logger
 */

import { useCallback, useEffect, useState } from 'react';
import type { ReactElement } from 'react';
import { PageHeader } from '../../app/PageHeader';
import { supabase } from '../../data/supabase.ts';
import './referral.css';

// Interface for Referral Draft Payload stored inside application_events detail JSONB
interface ReferralDraftDetail {
  companyName: string;
  jobTitle: string;
  recipientRole: string;
  subject: string;
  body: string;
  notes: string;
  generatedAt: string;
}

// Interface for Referral Event Row joined with application and job metadata
interface ReferralEventItem {
  id: string;
  applicationId: string;
  jobTitle: string;
  companyName: string;
  locationRaw: string | null;
  draft: ReferralDraftDetail;
  createdAt: string;
  sentAt?: string | null;
}

export function ReferralOutreachPage(): ReactElement {
  // State holding fetched referral outreach items
  const [items, setItems] = useState<readonly ReferralEventItem[]>([]);
  // State holding loading indicator boolean
  const [loading, setLoading] = useState<boolean>(true);
  // State holding copy toast confirmation string
  const [copiedId, setCopiedId] = useState<string | null>(null);
  // State holding set of sent item IDs
  const [sentIds, setSentIds] = useState<Set<string>>(new Set());

  // Fetch drafted referral outreach items from application_events table
  const loadReferrals = useCallback(async () => {
    try {
      setLoading(true);
      if (supabase === null) {
        setLoading(false);
        return;
      }

      // Query application_events for referral outreach drafted events
      const { data, error } = await supabase!
        .from('application_events')
        .select('id, application_id, created_at, detail, applications(jobs(title, company_name, location_raw))')
        .eq('event_type', 'note')
        .order('created_at', { ascending: false })
        .limit(100);

      if (error || !data) {
        setLoading(false);
        return;
      }

      // Filter and map database records into ReferralEventItem shapes
      const mapped: ReferralEventItem[] = [];
      for (const row of data) {
        const detailObj = row.detail as Record<string, unknown> | null;
        if (detailObj && detailObj.action === 'referral_outreach_drafted' && detailObj.draft) {
          const draft = detailObj.draft as ReferralDraftDetail;
          const app = row.applications as unknown as { jobs?: { title?: string; company_name?: string; location_raw?: string } } | null;

          mapped.push({
            id: row.id,
            applicationId: row.application_id,
            jobTitle: app?.jobs?.title ?? draft.jobTitle ?? 'Software Engineer',
            companyName: app?.jobs?.company_name ?? draft.companyName ?? 'Company',
            locationRaw: app?.jobs?.location_raw ?? null,
            draft,
            createdAt: row.created_at,
          });
        }
      }

      setItems(mapped);
    } catch (err) {
      console.error('Failed to load referral outreach items:', err);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void loadReferrals();
  }, [loadReferrals]);

  // Copy draft subject and body to system clipboard
  const handleCopyDraft = async (item: ReferralEventItem) => {
    const textToCopy = `Subject: ${item.draft.subject}\n\n${item.draft.body}`;
    try {
      await navigator.clipboard.writeText(textToCopy);
      setCopiedId(item.id);
      setTimeout(() => setCopiedId(null), 2500);
    } catch (err) {
      console.error('Failed to copy referral draft:', err);
    }
  };

  // Open LinkedIn search in a new browser tab for company alumni
  const handleSearchLinkedInAlumni = (companyName: string) => {
    const searchQuery = `${companyName} alumni engineering software`;
    const linkedInUrl = `https://www.linkedin.com/search/results/people/?keywords=${encodeURIComponent(searchQuery)}`;
    window.open(linkedInUrl, '_blank', 'noopener,noreferrer');
  };

  // Mark referral outreach as sent in database
  const handleMarkSent = async (item: ReferralEventItem) => {
    try {
      if (supabase !== null) {
        // Log referral sent audit event into application_events
        await supabase!.from('application_events').insert({
          application_id: item.applicationId,
          event_type: 'note',
          agent: 'screener',
          detail: {
            action: 'referral_outreach_sent',
            company_name: item.companyName,
            job_title: item.jobTitle,
            sent_at: new Date().toISOString(),
          },
        });
      }

      setSentIds((prev) => new Set(prev).add(item.id));
    } catch (err) {
      console.error('Failed to mark referral as sent:', err);
    }
  };

  return (
    <div className="page page--wide referral-page">
      <PageHeader path="referrals" />

      {/* Header orientation banner */}
      <section className="referral-page__banner" aria-label="Referral Outreach Overview">
        <div>
          <h2>🤝 Referral Outreach Queue</h2>
          <p>
            Review AI-generated cold referral request message drafts. Use the one-click action buttons to copy text, find company alumni on LinkedIn, and record sent outreach.
          </p>
        </div>
        <div className="referral-page__meta-badge">
          <span>{items.length} Drafted Messages</span>
        </div>
      </section>

      {/* Referral cards list */}
      {loading ? (
        <div className="referral-page__empty">
          <p>Loading referral outreach drafts from database...</p>
        </div>
      ) : items.length === 0 ? (
        <div className="referral-page__empty">
          <p>No drafted referral requests found. As applications pass screening, referral drafts will appear here.</p>
        </div>
      ) : (
        <div className="referral-page__grid">
          {items.map((item) => {
            const isSent = sentIds.has(item.id);

            return (
              <article key={item.id} className={`referral-card ${isSent ? 'referral-card--sent' : ''}`}>
                <header className="referral-card__header">
                  <div className="referral-card__top">
                    <span className="referral-card__company">{item.companyName}</span>
                    <span className="referral-card__role-pill">
                      🎯 Target: {item.draft.recipientRole || 'Peer Engineer / Recruiter'}
                    </span>
                  </div>
                  <h3 className="referral-card__title">{item.jobTitle}</h3>
                  {item.locationRaw && (
                    <span className="referral-card__location">📍 {item.locationRaw}</span>
                  )}
                </header>

                <div className="referral-card__body-box">
                  <div className="referral-card__subject">
                    <strong>Subject:</strong> {item.draft.subject}
                  </div>
                  <div className="referral-card__message">{item.draft.body}</div>
                </div>

                {item.draft.notes && (
                  <div className="referral-card__notes">
                    <strong>💡 Networking Strategy:</strong> {item.draft.notes}
                  </div>
                )}

                <footer className="referral-card__footer">
                  <div className="referral-card__actions">
                    <button
                      type="button"
                      className="button button--primary button--small"
                      onClick={() => void handleCopyDraft(item)}
                    >
                      {copiedId === item.id ? '✓ Copied Subject & Body!' : '📋 Copy Message'}
                    </button>

                    <button
                      type="button"
                      className="button button--secondary button--small"
                      onClick={() => handleSearchLinkedInAlumni(item.companyName)}
                      title="Search LinkedIn for company contacts and alumni"
                    >
                      🔗 Find Alumni on LinkedIn ↗
                    </button>

                    <button
                      type="button"
                      className={`button button--small ${isSent ? 'button--disabled' : 'button--secondary'}`}
                      onClick={() => void handleMarkSent(item)}
                      disabled={isSent}
                    >
                      {isSent ? '✓ Sent Recorded' : '✅ Mark as Sent'}
                    </button>
                  </div>
                </footer>
              </article>
            );
          })}
        </div>
      )}
    </div>
  );
}
